double getLibertyTimelinePixelsPerSecond() noexcept; int getLibertyTrackRowHeight() noexcept;
namespace{constexpr int headerWidth=210,transportHeight=76,rulerHeight=32,totalTrackRows=AudioEngine::maxAudioTracks+2;std::atomic<int>snapIndex{3};juce::String snapLabel(int i){switch(i){case 0:return"OFF";case 1:return"1/4";case 2:return"1/8";case 3:return"1/16";case 4:return"1/32";case 5:return"1/8T";case 6:return"1/16T";default:return"1/16";}}double snapSecondsFor(const MainComponent&o){auto i=snapIndex.load();if(!i)return 0;double q=60.0/juce::jmax(1.0,o.tempoBpm);switch(i){case 1:return q;case 2:return q*.5;case 3:return q*.25;case 4:return q*.125;case 5:return q/3;case 6:return q/6;default:return q*.25;}}double snapTime(const MainComponent&o,double s){s=juce::jmax(0.0,s);auto st=snapSecondsFor(o);return st>0?std::round(s/st)*st:s;}
class GridSnapController final:public juce::Component,private juce::Timer{public:explicit GridSnapController(MainComponent&o):owner(o){setInterceptsMouseClicks(true,false);owner.addAndMakeVisible(this);setBounds(owner.getLocalBounds());startTimerHz(2);}~GridSnapController()override{shutdown();}void shutdown(){if(stopped.exchange(true))return;stopTimer();setVisible(false);}bool hitTest(int x,int y)override{if(snapButton().contains(x,y))return true;if(!snapIndex.load())return false;for(int t=0;t<owner.getAudioTrackCount();++t)if(audioClipBounds(t).contains(x,y))return true;return false;}void paint(juce::Graphics&g)override{drawGrid(g);drawSnapButton(g);}void mouseDown(const juce::MouseEvent&e)override{if(snapButton().contains(e.getPosition())){showSnapMenu();return;}int t=audioTrackAt(e.getPosition());if(t>=0&&audioClipBounds(t).contains(e.getPosition())){owner.selectedTrack=t;draggingAudio=true;draggedTrack=t;dragMouseX=e.position.x;dragStartSeconds=owner.audioEngine.getTrackStartSeconds(t);owner.repaint();}}void mouseDrag(const juce::MouseEvent&e)override{if(!draggingAudio||draggedTrack<0)return;double p=getLibertyTimelinePixelsPerSecond(),d=((double)e.position.x-dragMouseX)/p;owner.audioEngine.setTrackStartSeconds(draggedTrack,snapTime(owner,dragStartSeconds+d));repaint();owner.repaint();}void mouseUp(const juce::MouseEvent&)override{draggingAudio=false;draggedTrack=-1;}
private:juce::Rectangle<int>snapButton()const{return{840,10,78,24};}juce::Rectangle<int>audioClipBounds(int t)const{if(t<0||t>=owner.getAudioTrackCount()||!owner.audioEngine.hasAudioFile(t))return{};int rh=getLibertyTrackRowHeight();double p=getLibertyTimelinePixelsPerSecond();int y=transportHeight+rulerHeight+(t-owner.getTrackScrollRows())*rh+4,x=headerWidth+(int)std::round(owner.audioEngine.getTrackStartSeconds(t)*p),w=juce::jmax(1,(int)std::round(owner.audioEngine.getAudioFileLengthSeconds(t)*p));return{x,y,w,rh-8};}int audioTrackAt(juce::Point<int>p)const{int rh=getLibertyTrackRowHeight(),y=p.y-transportHeight-rulerHeight;if(y<0)return-1;int t=y/rh;t+=owner.getTrackScrollRows();return t>=0&&t<owner.getAudioTrackCount()?t:-1;}void drawGrid(juce::Graphics&g){int rh=getLibertyTrackRowHeight();double p=getLibertyTimelinePixelsPerSecond();int top=transportHeight+rulerHeight,visibleRows=juce::jmax(1,(owner.getHeight()-210-top)/rh),bottom=juce::jmin(owner.getHeight()-210,top+visibleRows*rh);if(bottom<=top)return;for(int r=0;r<=visibleRows;++r){int y=top+r*rh;g.setColour(juce::Colour(0xff343a43).withAlpha(.78f));g.drawHorizontalLine(y,(float)headerWidth,(float)owner.getWidth());if(r<visibleRows){g.setColour(juce::Colour(0xff2a3038).withAlpha(.55f));g.drawHorizontalLine(y+rh/2,(float)headerWidth,(float)owner.getWidth());}}auto st=snapSecondsFor(owner);if(st<=0)st=60.0/juce::jmax(1.0,owner.tempoBpm);double ms=(60.0/juce::jmax(1.0,owner.tempoBpm))*(4.0/(double)juce::jmax(1,owner.timeSignatureDenominator))*(double)juce::jmax(1,owner.timeSignatureNumerator);for(int n=0;n<2000;++n){double s=n*st;int x=headerWidth+(int)std::round(s*p);if(x>owner.getWidth())break;bool major=ms>0&&std::abs(std::fmod(s,ms))<st*.15;g.setColour(major?juce::Colour(0xff59616d).withAlpha(.9f):juce::Colour(0xff343b45).withAlpha(.62f));g.drawVerticalLine(x,(float)top,(float)bottom);}}void drawSnapButton(juce::Graphics&g){auto r=snapButton();bool en=snapIndex.load()!=0;g.setColour(en?juce::Colour(0xff31506a):juce::Colour(0xff252a31));g.fillRoundedRectangle(r.toFloat(),5);g.setColour(juce::Colour(0xff59616d));g.drawRoundedRectangle(r.toFloat(),5,1);g.setColour(juce::Colours::white);g.setFont(juce::Font(9.0f,juce::Font::bold));g.drawText("SNAP "+snapLabel(snapIndex.load()),r,juce::Justification::centred);}void showSnapMenu(){juce::PopupMenu m;int cur=snapIndex.load();juce::StringArray l{"OFF","1/4","1/8","1/16","1/32","1/8T","1/16T"};for(int i=0;i<l.size();++i)m.addItem(i+1,l[i],true,cur==i);auto target=owner.localAreaToGlobal(snapButton());m.showMenuAsync(juce::PopupMenu::Options().withTargetScreenArea(target),[this](int r){if(r<=0)return;snapIndex.store(r-1);repaint();owner.repaint();});}void timerCallback()override{if(stopped.load())return;auto b=owner.getLocalBounds();if(getBounds()!=b){setBounds(b);repaint();}}MainComponent&owner;std::atomic<bool>stopped{false};bool draggingAudio=false;int draggedTrack=-1;float dragMouseX=0;double dragStartSeconds=0;};std::map<MainComponent*,std::unique_ptr<GridSnapController>>controllers;class Bootstrap final:private juce::Timer{public:Bootstrap(){startTimerHz(5);}~Bootstrap()override{shutdown();}void shutdown(){stopTimer();for(auto&p:controllers)if(p.second)p.second->shutdown();controllers.clear();}private:void timerCallback()override{auto&d=juce::Desktop::getInstance();for(int i=0;i<d.getNumComponents();++i)if(auto*w=dynamic_cast<juce::DocumentWindow*>(d.getComponent(i)))if(auto*m=dynamic_cast<MainComponent*>(w->getContentComponent()))if(!controllers.count(m))controllers.emplace(m,std::make_unique<GridSnapController>(*m));}};Bootstrap bootstrap;}
bool isLibertySnapEnabled()noexcept{return snapIndex.load()!=0;}double getLibertySnapSeconds(double bpm)noexcept{auto i=snapIndex.load();if(!i)return 0;double q=60.0/juce::jmax(1.0,bpm);switch(i){case 1:return q;case 2:return q*.5;case 3:return q*.25;case 4:return q*.125;case 5:return q/3;case 6:return q/6;default:return q*.25;}}void shutdownLibertyGridSnapController(){bootstrap.shutdown();}
